class Cache {
    static List<byte[]> dane = new ArrayList<>(); // pole statyczne - zyje tak dlugo, jak aplikacja
}

// gdziekolwiek w kodzie, wielokrotnie:
Cache.dane.add(new byte[1024 * 1024]); // BLAD: nic nigdy nie usuwa starych wpisow

class Cache {
    static final int LIMIT = 100;
    static List<byte[]> dane = new ArrayList<>();

    static void dodaj(byte[] wpis) {
        if (dane.size() >= LIMIT) {
            dane.remove(0); // swiadomie usuwamy najstarszy wpis, zanim dodamy nowy
        }
        dane.add(wpis);
    }
}

