static class CleanupDemo {
    @SuppressWarnings("deprecation")
    @Override
    protected void finalize() {
        System.out.println("GC: obiekt CleanupDemo usunięty!");
    }
}

// W main():
CleanupDemo demo = new CleanupDemo();
demo = null;
System.gc();
// finalize() jest ZDEPRECJONOWANA (od Javy 9) - jest NIEPRZEWIDYWALNA
// i może w ogóle się nie wykonać przed zakonczeniem programu.
// Preferuj AutoCloseable + try-with-resources dla deterministycznego sprzatania.

static class Resource implements AutoCloseable {
    @Override
    public void close() {
        System.out.println("Zasób zamkniety");
    }
}

// W main():
try (Resource r = new Resource()) {
    System.out.println("Uzywam zasobu");
}
// close() wywolane AUTOMATYCZNIE i DETERMINISTYCZNIE - to preferowane
// podejscie zamiast niedeterministycznej metody finalize().

static class NodeA { NodeB partner; }
static class NodeB { NodeA partner; }

// W main():
