String a1 = "literal1", a2 = "literal2", a3 = "literal3";
String b1 = new String("new1"), b2 = new String("new2"), b3 = new String("new3");
// Literaly (a1, a2, a3) są przechowywane w String Poolu - specjalnym obszarze
