System.out.println("Wzrosla: " + (freeAfter > freeBefore));

java.util.List<byte[]> leakyList = new java.util.ArrayList<>();
Runtime runtime = Runtime.getRuntime();
for (int i = 0; i < 30; i++) {
    leakyList.add(new byte[100 * 1024]); // 100KB każda
    if (i % 10 == 0) {
        System.out.println("Iteracja " + i + ", freeMemory: " + runtime.freeMemory());
    }
}
leakyList.clear();
System.gc();
System.out.println("Po wyczyszczeniu listy i GC, freeMemory: " + runtime.freeMemory());
// Statyczne (lub długo zyjace) kolekcje, do których CIAGLE dodaje się dane
// bez ograniczeń, są CZESTYM źródłem wyciekow pamięci - obiekty w nich
// pozostają OSIĄGALNE (przez referencje z kolekcji), więc GC nie może ich usunąć.

